using namespace std;

struct Competitor {
    int s, r, id;
    Competitor(int s, int r, int id) : s(s), r(r), id(id) {}
};

bool cmp(const Competitor& a, const Competitor& b) {
    return a.s * b.r < b.s * a.r;
}

int main() {
    int n;
    cin >> n;
    vector<Competitor> com(n);
    for (int i = 0; i < n; ++i) {
        int s, r;
        cin >> s >> r;
        com[i] = Competitor(s, r, i + 1);
    }
    sort(com.begin(), com.end(), cmp);
    map<int, int> cnt;
    for (int i = 0; i < n; ++i) {
        cnt[com[i].id] = 1;
        for (int j = 0; j < i; ++j) {
            if (com[i].s * com[j].r > com[j].s * com[i].r) {
                cnt[com[j].id] = 0;
            }
        }
    }
    vector<int> ans;
    for (auto& it : cnt) {
        if (it.second) {
            ans.push_back(it.first);
        }
    }
    sort(ans.begin(), ans.end());
    for (auto& it : ans) {
        cout << it << " ";
    }
    cout << endl;
    return 0;
}

#include <iostream>
#include <string>

bool isEquivalent(const std::string& a, const std::string& b) {
    if (a == b) return true;
    if (a.size() % 2!= 0) return false;

    int mid = a.size() / 2;
    std::string a1 = a.substr(0, mid);
    std::string a2 = a.substr(mid);
    std::string b1 = b.substr(0, mid);
    std::string b2 = b.substr(mid);

    return (isEquivalent(a1, b1) && isEquivalent(a2, b2)) ||
           (isEquivalent(a1, b2) && isEquivalent(a2, b1));
}

int main() {
    std::string a, b;
    std::cin >> a >> b;

    if (isEquivalent(a, b)) {
        std::cout << "YES" << std::endl;
    } else {
        std::cout << "NO" << std::endl;
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <climits>

using namespace std;

const int N = 25;
const int INF = INT_MAX;

int n;
int a[N][3];
int best[N + 1][N * N * 3 + N];
int who[N + 1][N * N * 3 + N];
int best2[N + 1][N * N * 3 + N];
int who2[N + 1][N * N * 3 + N];

void solve(int n, int a[][3], int best[][N * N * 3 + N], int who[][N * N * 3 + N]) {
    for (int i = 0; i <= n; i++) {
        for (int j = 0; j <= N * N * 3 + N; j++) {
            best[i][j] = -INF;
        }
    }
    best[0][N] = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j <= N * N * 3 + N; j++) {
            if (best[i][j]!= -INF) {
                best[i + 1][j + a[i][0]] = max(best[i + 1][j + a[i][0]], best[i][j]);
                who[i + 1][j + a[i][0]] = 0;
                best[i + 1][j + a[i][1]] = max(best[i + 1][j + a[i][1]], best[i][j]);
                who[i + 1][j + a[i][1]] = 1;
                best[i + 1][j + a[i][2]] = max(best[i + 1][j + a[i][2]], best[i][j]);
                who[i + 1][j + a[i][2]] = 2;
            }
        }
    }
}

int main() {
    cin >> n;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < 3; j++) {
            cin >> a[i][j];
        }
    }
    solve(n, a, best, who);
    solve(n, a, best2, who2);
    for (int i = 0; i <= n; i++) {
        for (int j = 0; j <= N * N * 3 + N; j++) {
            best2[i][j] += j;
        }
    }
    int ans = -INF;
    int ansj = -1;
    for (int j = 0; j <= N * N * 3 + N; j++) {
        if (best[n][j]!= -INF && best2[n][j]!= -INF && best[n][j] + best2[n][j] > ans) {
            ans = best[n][j] + best2[n][j];
            ansj = j;
        }
    }
    if (ans == -INF) {
        cout << "Impossible" << endl;
        return 0;
    }
    vector<int> v1, v2;
    for (int i = n; i > 0; i--) {
        int w = who[i][ansj];
        v1.push_back(w);
        ansj -= a[i - 1][w];
    }
    ansj = ans - best[n][ansj];
    for (int i = n; i > 0; i--) {
        int w = who2[i][ansj];
        v2.push_back(w);
        ansj -= a[i - 1][w];
    }
    reverse(v1.begin(), v1.end());
    reverse(v2.begin(), v2.end());
    for (int i = 0; i < n; i++) {
        if (v1[i] == 0 && v2[i] == 1) {
            cout << "LM" << endl;
        } else if (v1[i] == 0 && v2[i] == 2) {
            cout << "LW" << endl;
        } else if (v1[i] == 1 && v2[i] == 0) {
            cout << "ML" << endl;
        } else if (v1[i] == 1 && v2[i] == 2) {
            cout << "MW" << endl;
        } else if (v1[i] == 2 && v2[i] == 0) {
            cout << "WL" << endl;
        } else if (v1[i] == 2 && v2[i] == 1) {
            cout << "WM" << endl;
        }
    }
    return 0;
}

