#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

struct Interval {
    long long l, r;
};

bool compareIntervals(const Interval& a, const Interval& b) {
    if (a.l == b.l) {
        return a.r > b.r;
    }
    return a.l < b.l;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    long long L;
    cin >> N >> L;

    vector<Interval> intervals(N);
    for (int i = 0; i < N; i++) {
        cin >> intervals[i].l >> intervals[i].r;
    }

    sort(intervals.begin(), intervals.end(), compareIntervals);

    int x = 0;
    long long current = 0;
    for (int i = 0; i < N; i++) {
        if (current < intervals[i].l) {
            x++;
            current = intervals[i].r;
        } else if (current < intervals[i].r) {
            current = intervals[i].r;
        }
    }

    int y = 0;
    for (int i = 0; i < N; i++) {
        bool covered = false;
        for (int j = 0; j < N; j++) {
            if (i!= j && intervals[j].l < intervals[i].r && intervals[i].l < intervals[j].r) {
                covered = true;
                break;
            }
        }
        if (!covered) {
            y++;
        }
    }

    cout << x << " " << y << endl;

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int INF = 1e9;
const int dx[4] = {1, 0, -1, 0};
const int dy[4] = {0, 1, 0, -1};

struct State {
    int x, y, apples, dist;
    State(int x, int y, int apples, int dist) : x(x), y(y), apples(apples), dist(dist) {}
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W, K;
    cin >> H >> W >> K;

    vector<string> grid(H);
    for (int i = 0; i < H; i++) {
        cin >> grid[i];
    }

    int sx, sy, ex, ey;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (grid[i][j] == 's') {
                sx = i;
                sy = j;
            } else if (grid[i][j] == 'e') {
                ex = i;
                ey = j;
            }
        }
    }

    vector<vector<vector<int>>> dist(H, vector<vector<int>>(W, vector<int>(1 << 20, INF)));
    queue<State> q;
    q.push(State(sx, sy, 0, 0));
    dist[sx][sy][0] = 0;

    while (!q.empty()) {
        State state = q.front();
        q.pop();

        for (int i = 0; i < 4; i++) {
            int nx = state.x + dx[i];
            int ny = state.y + dy[i];

            if (nx < 0 || nx >= H || ny < 0 || ny >= W || grid[nx][ny] == '#') {
                continue;
            }

            int napples = state.apples;
            if (grid[nx][ny] == 'a') {
                napples++;
            }

            if (dist[nx][ny][napples] > state.dist + 1) {
                dist[nx][ny][napples] = state.dist + 1;
                q.push(State(nx, ny, napples, state.dist + 1));
            }
        }
    }

    int ans = INF;
    for (int i = K; i < (1 << 20); i++) {
        if (dist[ex][ey][i] < ans) {
            ans = dist[ex][ey][i];
        }
    }

    if (ans == INF) {
        cout << -1 << endl;
    } else {
        cout << ans << endl;
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <limits>
#include <algorithm>

using namespace std;

const int INF = numeric_limits<int>::max();

struct Edge {
    int source;
    int target;
    int weight;
};

int main() {
    int numVertices, numEdges, root;
    cin >> numVertices >> numEdges >> root;

    vector<Edge> edges;
    for (int i = 0; i < numEdges; ++i) {
        Edge edge;
        cin >> edge.source >> edge.target >> edge.weight;
        edges.push_back(edge);
    }

    vector<int> distances(numVertices, INF);
    distances[root] = 0;

    vector<bool> visited(numVertices, false);

    int sumWeights = 0;
    while (!visited[root]) {
        int minWeight = INF;
        Edge minEdge;

        for (const Edge& edge : edges) {
            if (distances[edge.source] != INF && !visited[edge.target] && edge.weight < minWeight && edge.source != edge.target) {
                minWeight = edge.weight;
                minEdge = edge;
            }
        }

        if (minWeight == INF) {
            break;
        }

        distances[minEdge.target] = min(distances[minEdge.target], minWeight);
        sumWeights += minWeight;
        visited[minEdge.target] = true;
    }

    for (int i = 0; i < numVertices; ++i) {
        if (distances[i] == INF) {
            bool found = false;
            for (const Edge& edge : edges) {
                if (edge.target == i && distances[edge.source] != INF) {
                    found = true;
                    sumWeights += edge.weight;
                    distances[i] = edge.weight;
                    break;
                }
            }

            if (!found) {
                for (const Edge& edge : edges) {
                    if (visited[edge.target] && distances[edge.source] != INF) {
                        sumWeights += edge.weight;
                        break;
                    }
                }
            }
        }
    }

    cout << sumWeights << endl;

    return 0;
}

#include <iostream>
