void dfs(int u, int par) {
    double sum = 1 - p[u];
    for (int v : adj[u]) {
        if (v!= par) {
            dfs(v, u);
            sum += (1 - p[v]) * (1 - p[u]);
        }
    }
    ans += sum;
}

