    cin >> q;

    while (q--) {
        int u;
        double new_p;
        cin >> u >> new_p;
        double old_p = p[u];
        p[u] = new_p;

        ans = 0;
        dfs(0, -1);
        cout << fixed;
        cout.precision(5);
        cout << ans << '\n';
    }

    return 0;
}

