    multiset<pii> st;
    int cur = 0;
    for (int i = 0; i < n; i++) {
        for (auto& p : events[i]) {
            if (p.first > 0) {
                st.insert({p.second, p.first});
                cur += p.first;
            } else {
                auto it = st.find({-p.second, -p.first});
                if (it!= st.end()) {
                    st.erase(it);
                    cur += p.first;
                }
            }
        }

        int need = min(k, cur);
        ll cost = 0;
        while (need > 0 &&!st.empty()) {
            auto it = st.begin();
            int take = min(need, it->second);
            need -= take;
            cost += (ll)take * it->first;
            if (take < it->second) {
                st.erase(it);
                st.insert({it->first, it->second - take});
            }
        }
        ans += cost;
    }

    cout << ans << '\n';

    return 0;
}

