const int MAXN = 1000;

vector<int> g[MAXN];
bool used[MAXN];
int tin[MAXN], fup[MAXN];
int timer;
vector<int> bridges;
vector<pair<int, int>> ans;

void dfs(int v, int p = -1) {
    used[v] = true;
    tin[v] = fup[v] = timer++;
    for (int to : g[v]) {
        if (to == p) continue;
        if (used[to]) {
            fup[v] = min(fup[v], tin[to]);
        } else {
            dfs(to, v);
            fup[v] = min(fup[v], fup[to]);
            if (fup[to] > tin[v]) {
                bridges.push_back(to);
            }
        }
    }
}

