        cin >> a >> b;
        a--, b--;
        g[a].push_back(b);
        g[b].push_back(a);
    }

    dfs(0);

    if (bridges.empty()) {
        cout << 0 << endl;
        return 0;
    }

    vector<int> deg(n, 0);
    for (int i = 0; i < n; i++) {
        for (int to : g[i]) {
            deg[i]++;
        }
    }

    vector<int> leaves;
    for (int i = 0; i < n; i++) {
        if (deg[i] == 1) {
            leaves.push_back(i);
        }
    }

    if (leaves.size() <= 2) {
