        return 0;
    }

    for (int i = 0; i < leaves.size(); i++) {
        for (int j = i + 1; j < leaves.size(); j++) {
            int a = leaves[i], b = leaves[j];
            if (find(g[a].begin(), g[a].end(), b) == g[a].end()) {
                ans.push_back({a, b});
            }
        }
    }

    if (ans.size() == 0) {
        cout << -1 << endl;
        return 0;
    }

    cout << ans.size() << endl;
    for (auto p : ans) {
