const int N = 7;
const int INF = 1e9 + 7;

int n;
int likes[N][N];
int exp[N];
int dp[1 << N][N][N];
int ans = INF, ans2 = 0;

void dfs(int mask, int a, int b) {
    if (mask == (1 << n) - 1) {
        int c = n - a - b;
        int x = exp[0] / a, y = exp[1] / b, z = exp[2] / c;
        int diff = max({x, y, z}) - min({x, y, z});
        if (diff < ans) {
            ans = diff;
            ans2 = dp[mask][a][b];
        } else if (diff == ans) {
            ans2 = max(ans2, dp[mask][a][b]);
        }
        return;
    }
    for (int i = 0; i < n; i++) {
        if (!(mask & (1 << i))) {
            int cnt = __builtin_popcount(mask);
            int new_mask = mask | (1 << i);
            int new_a = a + 1, new_b = b;
            if (new_a > n / 2) {
                new_a = a;
                new_b = b + 1;
            }
            dp[new_mask][new_a][new_b] = dp[mask][a][b];
            for (int j = 0; j < n; j++) {
                if (mask & (1 << j)) {
                    dp[new_mask][new_a][new_b] += likes[i][j];
                }
            }
            dfs(new_mask, new_a, new_b);
        }
    }
}

