const int N = 1e5 + 5;

vector<pr> g[N], tree[N];
int level[N], par[N];
bool vis[N];

void dfs(int src) {
    vis[src] = true;
    for (auto &e : g[src]) {
        int child = e.fi, rel = e.se;
        if (!vis[child]) {
            par[child] = src;
            level[child] = level[src] + 1;
            if (rel == 0) {
                tree[src].pb({child, 0});
                tree[child].pb({src, 1});
            } else {
                tree[child].pb({src, 0});
                tree[src].pb({child, 1});
            }
            dfs(child);
        }
    }
}

int lca(int u, int v) {
    if (level[u] < level[v]) {
        swap(u, v);
    }
    while (level[u] != level[v]) {
        u = par[u];
    }
    while (u != v) {
        u = par[u];
        v = par[v];
    }
    return u;
}

bool isSpecialCase(int u, int v) {
    return (level[u] > level[v] && lca(u, v) == v);
}

bool isPartOf(int u, int v) {
    return (level[u] < level[v] && lca(u, v) == u);
}

int main() {
    FAST_IO;

    int n;
    cin >> n;

    REP(i, n) {
        int p, rel;
        cin >> p >> rel;
        if (p != -1) {
            g[p - 1].pb({i, rel});
        } else {
            level[i] = 0;
            par[i] = -1;
        }
    }

    REP(i, n) {
        if (!vis[i]) {
            dfs(i);
        }
    }

    int q;
    cin >> q;
    while (q--) {
        int t, u, v;
        cin >> t >> u >> v;
        u--, v--;

        if (t == 1) {
            if (isSpecialCase(v, u)) {
                cout << "YES" << endl;
            } else {
                cout << "NO" << endl;
            }
        } else {
            if (isPartOf(u, v)) {
                cout << "YES" << endl;
            } else {
                cout << "NO" << endl;
            }
        }
    }

    return 0;
}

#include <iostream>
#include <string>
#include <map>

using namespace std;

map<string, int> types;

int resolveType(const string& type) {
    int ampersands = 0;
    int asterisks = 0;
    int i = 0;
    while (type[i] == '&') {
        ampersands++;
        i++;
    }
    i = type.size() - 1;
    while (type[i] == '*') {
        asterisks++;
        i--;
    }
    string name = type.substr(ampersands, type.size() - ampersands - asterisks);
    if (name == "void") {
        if (ampersands > 0) {
            return -1; // errtype
        } else {
            return asterisks;
        }
    } else if (name == "errtype") {
        return -1; // errtype
    } else {
        if (types.find(name) == types.end()) {
            return -1; // errtype
        }
        int value = types[name];
        if (value == -1) {
            return -1; // errtype
        }
        value += asterisks;
        value -= ampersands;
        if (value < 0) {
            return -1; // errtype
        }
        return value;
    }
}

int main() {
    int n;
    cin >> n;
    for (int i = 0; i < n; i++) {
        string command;
        cin >> command;
        if (command == "typedef") {
            string type, name;
            cin >> type >> name;
            int value = resolveType(type);
            types[name] = value;
        } else if (command == "typeof") {
            string type;
            cin >> type;
            int value = resolveType(type);
            if (value == -1) {
                cout << "errtype" << endl;
            } else {
                cout << "void";
                for (int j = 0; j < value; j++) {
                    cout << "*";
                }
                cout << endl;
            }
        }
    }
    return 0;
}

