const double EPS = 1e-8;

int n, s, t;
int q[MAXN];
int a[MAXN][MAXN];
double f[MAXN];
double d[MAXN];
int deg[MAXN];

void solve() {
    cin >> n >> s >> t;
    for (int i = 1; i <= n; i++) {
        cin >> q[i];
    }
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            cin >> a[i][j];
        }
    }

    for (int i = 1; i <= n; i++) {
        f[i] = 0;
        d[i] = 0;
        deg[i] = 0;
    }

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            if (a[i][j] > 0) {
                deg[i]++;
            }
        }
    }

    queue<int> q;
    q.push(t);
    f[t] = 1;

    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int v = 1; v <= n; v++) {
            if (a[u][v] > 0) {
                if (f[v] == 0) {
                    q.push(v);
                }
                f[v] = 1;
            }
        }
    }

    if (f[s] == 0) {
        cout << "impossible" << endl;
        return;
    }

    for (int i = 1; i <= n; i++) {
        if (f[i] == 0) {
            continue;
        }
        if (i == t) {
            continue;
        }
        if (q[i] == 1) {
            int cnt = 0;
            double sum = 0;
            for (int j = 1; j <= n; j++) {
                if (a[i][j] > 0 && f[j] == 1) {
                    cnt++;
                    sum += a[i][j];
                }
            }
            for (int j = 1; j <= n; j++) {
                if (a[i][j] > 0 && f[j] == 1) {
                    d[j] += d[i] + a[i][j] - sum / cnt;
                }
            }
        } else {
            for (int j = 1; j <= n; j++) {
                if (a[i][j] > 0 && f[j] == 1) {
                    d[j] += d[i] + a[i][j];
                }
            }
        }
    }

    cout << fixed << setprecision(8) << d[s] << endl;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    while (true) {
        solve();
        if (cin.peek() == '0') {
            break;
        }
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <string>
#include <algorithm>

using namespace std;

typedef long long ll;

const ll mod = 1e9 + 7;

ll n, m, k;
vector<string> words;

ll dp[2005];

void solve() {
    cin >> n >> m >> k;
    words.resize(n);
    for (int i = 0; i < n; i++) {
        cin >> words[i];
    }
    sort(words.begin(), words.end());
    dp[0] = 1;
    for (int i = 1; i <= m; i++) {
        for (int j = 0; j < n; j++) {
            if (i - words[j].size() >= 0) {
                dp[i] += dp[i - words[j].size()];
            }
        }
    }
    if (dp[m] < k) {
        cout << "-" << endl;
        return;
    }
    string ans = "";
    k--;
    for (int i = m; i > 0; i--) {
        for (int j = 0; j < n; j++) {
            if (i - words[j].size() >= 0) {
                if (k - dp[i - words[j].size()] >= 0) {
                    k -= dp[i - words[j].size()];
                } else {
                    ans += words[j];
                    i -= words[j].size();
                    break;
                }
            }
        }
    }
    cout << ans << endl;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);
    solve();
    return 0;
}

#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>

using namespace std;

const int MAX_N = 100;
const double EPS = 1e-6;

struct Point {
    double x, y;
};

struct Parabola {
    double a, p, q;
};

double calcY(const Parabola& para, double x) {
    return para.a * (x - para.p) * (x - para.p) + para.q;
}

double calcX(const Parabola& para, double y) {
    return para.p + sqrt((y - para.q) / para.a);
}

double calcX2(const Parabola& para, double y) {
    return para.p - sqrt((y - para.q) / para.a);
}

double calcLength(const Parabola& para, double x1, double x2) {
    double y1 = calcY(para, x1);
    double y2 = calcY(para, x2);
    double dx = x2 - x1;
    double dy = y2 - y1;
    return sqrt(dx * dx + dy * dy);
}

int main() {
    int W, H, N;
    cin >> W >> H >> N;

    vector<Parabola> paras(N);
    for (int i = 0; i < N; i++) {
        cin >> paras[i].a >> paras[i].p >> paras[i].q;
    }

    double ans = 0.0;
    for (int i = 0; i < N; i++) {
        double x1 = max(0.0, calcX2(paras[i], 0.0));
        double x2 = min(W, calcX(paras[i], 0.0));
        if (x1 < x2) {
            ans += calcLength(paras[i], x1, x2);
        }
    }

    cout << fixed;
    cout.precision(20);
    cout << ans << endl;

    return 0;
}

#include <iostream>
#include <vector>
#include <queue>
#include <climits>
#include <cstring>

using namespace std;

const int MAX_N = 100;
const int MAX_M = MAX_N * (MAX_N - 1) / 2;
const int MAX_E = 4;

struct Edge {
    int to, next;
};

int n, m, e, s, t, r;
Edge edge[MAX_M * 2];
int head[MAX_N], cnt;
int event[MAX_E][3];

void addEdge(int u, int v) {
    edge[cnt].to = v;
    edge[cnt].next = head[u];
    head[u] = cnt++;
}

int dis[MAX_N][1 << MAX_E];
bool vis[MAX_N][1 << MAX_E];

void bfs(int S, int mask) {
    queue<int> q;
    memset(dis, 0x3f, sizeof(dis));
    memset(vis, 0, sizeof(vis));
    dis[S][mask] = 0;
    vis[S][mask] = true;
    q.push(S);
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int i = head[u]; i!= -1; i = edge[i].next) {
            int v = edge[i].to;
            if (!vis[v][mask]) {
                dis[v][mask] = dis[u][mask] + 1;
                vis[v][mask] = true;
                q.push(v);
            }
        }
        for (int i = 0; i < e; i++) {
            if ((mask >> i) & 1) continue;
            if (u == event[i][2]) {
                int newMask = mask | (1 << i);
                for (int j = head[u]; j!= -1; j = edge[j].next) {
                    int v = edge[j].to;
                    if (!vis[v][newMask]) {
                        dis[v][newMask] = dis[u][mask] + 1;
                        vis[v][newMask] = true;
                        q.push(v);
                    }
                }
            }
        }
    }
}

int main() {
    cin >> n >> m >> e >> s >> t >> r;
    memset(head, -1, sizeof(head));
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        addEdge(u, v);
        addEdge(v, u);
    }
    for (int i = 0; i < e; i++) {
        cin >> event[i][0] >> event[i][1] >> event[i][2];
    }
    int ans = INT_MAX;
    for (int mask = 0; mask < (1 << e); mask++) {
        bfs(s, mask);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < (1 << e); j++) {
                if (dis[i][j]!= INT_MAX) {
                    for (int k = 0; k < e; k++) {
                        if ((j >> k) & 1) {
                            addEdge(event[k][0], event[k][1]);
                            addEdge(event[k][1], event[k][0]);
                        }
                    }
                    int tmp = dis[i][j];
                    for (int k = 0; k < (1 << e); k++) {
                        if (dis[t][k]!= INT_MAX) {
                            ans = min(ans, tmp + dis[t][k] + __builtin_popcount(k));
                        }
                    }
                    for (int k = 0; k < e; k++) {
                        if ((j >> k) & 1) {
                            for (int l = head[event[k][0]]; l!= -1; l = edge[l].next) {
                                if (edge[l].to == event[k][1]) {
                                    edge[l].to = -1;
                                    edge[l ^ 1].to = -1;
                                    break;
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    if (ans == INT_MAX) {
        cout << -1 << endl;
    } else {
        cout << ans << endl;
    }
    return 0;
}

#include <iostream>
