using namespace std;

int main() {
    int n, m;
    cin >> n >> m;

    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    vector<int> b = a;
    sort(b.begin(), b.end());

    vector<int> c = a;
    sort(c.rbegin(), c.rend());

    int sum1 = 0, sum2 = 0;
    for (int i = 0; i < n; ++i) {
        sum1 += abs(b[i] - i);
        sum2 += abs(c[i] - i);
    }

    int ans = max(sum1, sum2);

    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            if (m == 0) break;
            swap(a[i], a[j]);
            m--;
            int sum = 0;
            for (int k = 0; k < n; ++k) {
                sum += abs(a[k] - k);
            }
            ans = max(ans, sum);
            swap(a[i], a[j]);
        }
    }

    cout << ans << endl;

    return 0;
}

#include <iostream>
#include <string>
#include <vector>

using namespace std;

const int MOD = 1e9 + 7;

int main() {
    string S, T;
    cin >> S >> T;

    int n = S.size();
    vector<long long> dp(n + 1, 0);
    dp[0] = 1;

    for (int i = 0; i < n; i++) {
        vector<long long> next(n + 1, 0);
        if (T[i] == '?') {
            for (int j = 0; j <= n; j++) {
                for (int k = 0; k <= 9; k++) {
                    if (j < n && k > S[i] - '0') break;
                    next[j + (k > S[i] - '0')] += dp[j];
                    next[j + (k > S[i] - '0')] %= MOD;
                }
            }
        } else {
            for (int j = 0; j <= n; j++) {
                int k = T[i] - '0';
                if (j < n && k > S[i] - '0') break;
                next[j + (k > S[i] - '0')] += dp[j];
                next[j + (k > S[i] - '0')] %= MOD;
            }
        }
        dp = next;
    }

    long long ans = 0;
    for (int i = 0; i <= n; i++) {
        ans += dp[i] * (i == 0? 0 : 1);
        ans %= MOD;
    }

    long long pow10 = 1;
    for (int i = 0; i < n; i++) {
        if (T[i] == '?') {
            ans *= 10;
            ans %= MOD;
        } else {
            ans *= 1;
            ans += (T[i] - '0') * pow10;
            ans %= MOD;
        }
        pow10 *= 10;
        pow10 %= MOD;
    }

    cout << ans << endl;

    return 0;
}

#include <iostream>
#include <vector>
#include <stack>
#include <algorithm>

using namespace std;

int main() {
    int H, W;
    cin >> H >> W;

    vector<vector<int>> A(H, vector<int>(W));
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            cin >> A[i][j];
        }
    }

    vector<int> height(W, 0);
    int ans = 0;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (A[i][j] == 0) {
                height[j]++;
            } else {
                height[j] = 0;
            }
        }

        stack<int> st;
        int w = 0;
        for (int j = 0; j <= W; j++) {
            while (!st.empty() && (j == W || height[st.top()] > height[j])) {
                int h = height[st.top()];
                st.pop();
                w = j;
                if (!st.empty()) {
                    w = j - st.top() - 1;
                }
                ans = max(ans, h * w);
            }
            st.push(j);
        }
    }

    cout << ans << endl;

    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
#include <numeric>

int main() {
    std::string a, b;
    std::cin >> a >> b;

    while (a.size() < b.size()) a = '0' + a;
    while (b.size() < a.size()) b = '0' + b;

    std::string result;
    int carry = 0;

    for (int i = a.size() - 1; i >= 0; --i) {
        int sum = (a[i] - '0') + (b[i] - '0') + carry;
        result.push_back('0' + sum % 10);
        carry = sum / 10;
    }

    if (carry) result.push_back('0' + carry);

    std::reverse(result.begin(), result.end());

    while (result.size() > 1 && result[0] == '0') result.erase(0, 1);

    std::cout << result << std::endl;

    return 0;
}

#include <bits/stdc++.h>

using namespace std;

int getWeight(char c) {
    return c - 'a' + 1;
}

int main() {
    int n, k;
    cin >> n >> k;

    string s;
    cin >> s;

    sort(s.begin(), s.end());

    vector<bool> used(n, false);
    int ans = -1;
    vector<vector<int>> dp(n + 1, vector<int>(k + 1, -1));
    dp[0][0] = 0;

    for (int i = 0; i < n; i++) {
        for (int j = k; j >= 1; j--) {
            if (dp[i][j - 1] != -1) {
                int prevWeight = (i > 0 && used[i - 1]) ? getWeight(s[i - 1]) : 0;
                if (getWeight(s[i]) - prevWeight >= 2) {
                    int newWeight = dp[i][j - 1] + getWeight(s[i]);
                    if (dp[i + 1][j] == -1 || newWeight < dp[i + 1][j]) {
                        dp[i + 1][j] = newWeight;
                        used[i] = true;
                    }
                }
            }
        }
        if (dp[i + 1][k] != -1 && (ans == -1 || dp[i + 1][k] < ans)) {
            ans = dp[i + 1][k];
        }
    }

    cout << ans << endl;

    return 0;
}

