using namespace std;

int main() {
    int n, L, a;
    cin >> n >> L >> a;

    vector<pair<int, int>> customers(n);
    for (int i = 0; i < n; ++i) {
        cin >> customers[i].first >> customers[i].second;
    }

    int maxBreaks = 0;
    int currentTime = 0;

    if (n == 0) {
        maxBreaks = (L / a);
    } else {
        for (int i = 0; i < n; ++i) {
            int availableTime = customers[i].first - currentTime;
            maxBreaks += (availableTime / a);
            currentTime = customers[i].first + customers[i].second;
        }

        int remainingTime = L - currentTime;
        maxBreaks += (remainingTime / a);
    }

    cout << maxBreaks << endl;

    return 0;
}

#include <iostream>

int main() {
    int t;
    std::cin >> t;

    for (int i = 0; i < t; i++) {
        int n, m;
        std::cin >> n >> m;

        int x1, y1, x2, y2;
        std::cin >> x1 >> y1 >> x2 >> y2;

        int x3, y3, x4, y4;
        std::cin >> x3 >> y3 >> x4 >> y4;

        long long black = (n * m) / 2;
        long long white = (n * m) / 2;

        if ((n * m) % 2 != 0) {
            if ((n + m) % 2 == 0) {
                black++;
            } else {
                white++;
            }
        }

        long long firstWhite = (y2 - y1 + 1) * (x2 - x1 + 1);
        long long blackPart = 0;
        if ((x2 + y2) % 2 == 0) {
            blackPart = (firstWhite + 1) / 2;
        } else {
            blackPart = firstWhite / 2;
        }

        long long whitePart = firstWhite - blackPart;

        black -= blackPart;
        white += whitePart;

        long long secondBlack = (y4 - y3 + 1) * (x4 - x3 + 1);
        long long whitePartSecond = 0;
        if ((x4 + y4) % 2 == 0) {
            whitePartSecond = (secondBlack + 1) / 2;
        } else {
            whitePartSecond = secondBlack / 2;
        }

        long long blackPartSecond = secondBlack - whitePartSecond;

        long long intersectionWhiteBlack = 0;
        if (x3 <= x2 && x4 >= x1 && y3 <= y2 && y4 >= y1) {
            int intersectionX1 = std::max(x1, x3);
            int intersectionY1 = std::max(y1, y3);
            int intersectionX2 = std::min(x2, x4);
            int intersectionY2 = std::min(y2, y4);
            intersectionWhiteBlack = (intersectionY2 - intersectionY1 + 1) * (intersectionX2 - intersectionX1 + 1);

            if ((intersectionX2 + intersectionY2) % 2 == 0) {
                intersectionWhiteBlack = (intersectionWhiteBlack + 1) / 2;
            } else {
                intersectionWhiteBlack = intersectionWhiteBlack / 2;
            }
        }

        white -= intersectionWhiteBlack;
        black += blackPartSecond;

        std::cout << white << " " << black << std::endl;
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>

using namespace std;

int main() {
    int n, k;
    cin >> n >> k;

    vector<int> m(n);
    for (int i = 0; i < n; i++) {
        cin >> m[i];
    }

    vector<vector<int>> hall(k, vector<int>(k, 0));

    for (int i = 0; i < n; i++) {
        int mi = m[i];
        int min_sum = 1e9;
        int x = -1, yl = -1, yr = -1;

        for (int j = 0; j < k; j++) {
            for (int l = 0; l <= k - mi; l++) {
                bool ok = true;
                for (int p = l; p < l + mi; p++) {
                    if (hall[j][p] == 1) {
                        ok = false;
                        break;
                    }
                }

                if (ok) {
                    int sum = 0;
                    for (int p = l; p < l + mi; p++) {
                        sum += (j - k / 2) * (j - k / 2) + (p - k / 2) * (p - k / 2);
                    }

                    if (sum < min_sum) {
                        min_sum = sum;
                        x = j + 1;
                        yl = l + 1;
                        yr = l + mi;
                    } else if (sum == min_sum) {
                        if (j < x - 1) {
                            x = j + 1;
                            yl = l + 1;
                            yr = l + mi;
                        } else if (j == x - 1 && l < yl - 1) {
                            x = j + 1;
                            yl = l + 1;
                            yr = l + mi;
                        }
                    }
                }
            }
        }

        if (x == -1) {
            cout << -1 << endl;
        } else {
            cout << x << " " << yl << " " << yr << endl;
            for (int p = yl - 1; p < yr; p++) {
                hall[x - 1][p] = 1;
            }
        }
    }

    return 0;
}

