    cin >> n;

    vector<int> p(n);
    for (int i = 0; i < n; i++) {
        cin >> p[i];
    }

    vector<pair<int, int>> ans;
    for (int i = 0; i < n / 2; i++) {
        if (p[i]!= i + 1) {
            int j = find(p.begin(), p.end(), i + 1) - p.begin();
            if (j < n / 2) {
