                if (p[k]!= i + 1) {
                    ans.push_back({k + 1, j + 1});
                    swap(p[k], p[j]);
                }
                ans.push_back({i + 1, k + 1});
                swap(p[i], p[k]);
            } else {
                ans.push_back({i + 1, j + 1});
                swap(p[i], p[j]);
            }
        }
    }

    cout << ans.size() << endl;
    for (auto& x : ans) {
        cout << x.first << " " << x.second << endl;
    }

    return 0;
}

