bool check(int a, int b) {
    string sa = to_string(a);
    string sb = to_string(b);
    int len = max(sa.length(), sb.length());
    sa = string(len - sa.length(), '0') + sa;
    sb = string(len - sb.length(), '0') + sb;
    for (int i = 0; i < len; i++) {
        if (sa[i] != '0' && sb[i] != '0') {
            return false;
        }
    }
    return true;
