        cin >> d[i];
    }

    vector<long long> h(n);
    for (int i = 0; i < n; i++) {
        cin >> h[i];
    }

    vector<long long> pref(n + 1, 0);
    for (int i = 0; i < n; i++) {
        pref[i + 1] = pref[i] + d[i];
    }

    vector<long long> dist(n, 0);
    for (int i = 0; i < n; i++) {
        dist[i] = pref[n] - pref[i] + pref[(i + 1) % n];
    }

    for (int i = 0; i < m; i++) {
        int a, b;
