                        y <= points[p].second && points[p].second < y + k) {
                        c++;
                    }
                }
                if (c > 0) count[c]++;
                y++;
                if (y > y2 - k + 1) {
                    y = y1;
                    x++;
                }
            }
        }
    }

    for (int i = 0; i < n; i++) {
