const int N = 1e5 + 5;

struct Edge {
    int u, v, w, id;
};

int n, m;
int x[N];
vector<Edge> edges;
vector<int> g[N];
int p[N], sz[N], sum[N];

int find(int x) {
    return x == p[x]? x : p[x] = find(p[x]);
}

void merge(int u, int v) {
    u = find(u);
    v = find(v);
    if (u == v) return;
    if (sz[u] < sz[v]) swap(u, v);
    p[v] = u;
    sz[u] += sz[v];
    sum[u] += sum[v];
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cin >> n >> m;
    for (int i = 1; i <= n; i++) {
