        sum[i] = x[i];
    }
    for (int i = 1; i <= m; i++) {
        int u, v, w;
        cin >> u >> v >> w;
        edges.push_back({u, v, w, i});
    }
    sort(edges.begin(), edges.end(), [](Edge a, Edge b) {
        return a.w < b.w;
    });
    int ans = 0;
    for (auto e : edges) {
        int u = find(e.u);
        int v = find(e.v);
        if (sum[u] + sum[v] < e.w) {
            ans++;
            continue;
        }
        merge(e.u, e.v);
    }
    cout << ans << endl;
    return 0;
}

