            } else {
                sum = m[i];
                right = L / 2.0 - R;
            }
        } else {
            sum += m[i];
        }

        if (i == N - 1) {
            cout << "Yes" << endl;
            return 0;
        }

        if (sum < M) {
            if (right >= -left) {
