using namespace std;

struct Edge {
    int u, v, w;
};

struct DisjointSet {
    vector<int> parent, rank;

    DisjointSet(int n) : parent(n), rank(n, 0) {
        for (int i = 0; i < n; i++) {
            parent[i] = i;
        }
    }

    int find(int x) {
        if (parent[x]!= x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    void unionSet(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX!= rootY) {
            if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } else if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
            } else {
                parent[rootY] = rootX;
                rank[rootX]++;
            }
        }
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;

    while (t--) {
        int n, m, k;
        cin >> n >> m >> k;

        vector<Edge> edges(m);
        for (int i = 0; i < m; i++) {
            cin >> edges[i].u >> edges[i].v >> edges[i].w;
            edges[i].u--;
            edges[i].v--;
        }

        sort(edges.begin(), edges.end(), [](const Edge& a, const Edge& b) {
            return a.w < b.w;
        });

        long long ans = numeric_limits<long long>::max();
        for (int mask = 0; mask < (1 << m); mask++) {
            if (__builtin_popcount(mask)!= n - 1) {
                continue;
            }

            DisjointSet dsu(n);
            vector<Edge> usedEdges;
            for (int i = 0; i < m; i++) {
                if ((mask >> i) & 1) {
                    dsu.unionSet(edges[i].u, edges[i].v);
                    usedEdges.push_back(edges[i]);
                }
            }

            bool connected = true;
            for (int i = 0; i < n; i++) {
                if (dsu.find(i)!= dsu.find(0)) {
                    connected = false;
                    break;
                }
            }

            if (!connected) {
                continue;
            }

            long long changes = 0;
            bool hasGreater = false;
            for (const auto& edge : usedEdges) {
                if (edge.w > k) {
                    changes += edge.w - k;
                } else if (edge.w < k) {
                    changes += k - edge.w;
                }
                if (edge.w > k) {
                    hasGreater = true;
                }
            }

            if (!hasGreater) {
                continue;
            }

            ans = min(ans, changes);
        }

        cout << ans << '\n';
    }

    return 0;
}

#include <iostream>
#include <string>
using namespace std;

bool find_smallest_beautiful_string(string &s, int k) {
    int n = s.size();
    int letters[26] = {0};
    for (char c : s) {
        letters[c - 'a']++;
    }
    bool updated = false;
    for (int i = 0; i < n; i++) {
        int idx = s[i] - 'a';
        if (letters[idx] % k != 0) {
            for (int j = idx + 1; j < 26; j++) {
                int required = k - (letters[idx] % k);
                if ((required + letters[j]) <= (n - i) && (letters[j] % k) == 0) {
                    s[i] = j + 'a';
                    letters[idx]--;
                    letters[j]++;
                    updated = true;
                    break;
                }
            }
        }
        if (updated) break;
    }
    if (!updated) {
        for (int i = 0; i < 26; i++) {
            if (letters[i] % k != 0) return false;
        }
        return true;
    }
    for (int i = n - 1; i > 0; i--) {
        if (s[i] > 'a') {
            s[i]--;
            for (int j = i + 1; j < n; j++) {
                s[j] = 'a';
            }
            for (char &c : s) {
                letters[c - 'a'] = 0;
            }
            for (char c : s) {
                letters[c - 'a']++;
            }
            for (int j = 0; j < 26; j++) {
                if (letters[j] % k != 0) {
                    int required = k - (letters[j] % k);
                    for (int x = j; x < 26; x++) {
                        if (required > 0) {
                            required--;
                            letters[x]++;
                            s[n - required - 1] = x + 'a';
                        } else break;
                    }
                }
            }
            return true;
        }
    }
    for (int i = 0; i < 26; i++) {
        if (letters[i] % k != 0) return false;
    }
    return true;
}

int main() {
    int T;
    cin >> T;
    for (int t = 0; t < T; t++) {
        int n, k;
        cin >> n >> k;
        string s;
        cin >> s;
        if (n % k != 0) {
            cout << -1 << endl;
            continue;
        }
        if (find_smallest_beautiful_string(s, k)) {
            cout << s << endl;
        } else {
            cout << -1 << endl;
        }
    }
    return 0;
}

#include <iostream>
